import{_ as a,o as e,c as r,a5 as o}from"./chunks/framework.BjM_ivYE.js";const p=JSON.parse('{"title":"배터리 한쪽만 소모","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/battery-one-side.md","filePath":"ko/manual/troubleshooting/battery-one-side.md","lastUpdated":1788840704000}'),l={name:"ko/manual/troubleshooting/battery-one-side.md"};function n(s,t,i,d,c,h){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="배터리-한쪽만-소모" tabindex="-1">배터리 한쪽만 소모 <a class="header-anchor" href="#배터리-한쪽만-소모" aria-label="Permalink to &quot;배터리 한쪽만 소모&quot;">​</a></h1><h2 id="single-pack-check" tabindex="-1">배터리를 하나씩 넣어 확인하기 <a class="header-anchor" href="#single-pack-check" aria-label="Permalink to &quot;배터리를 하나씩 넣어 확인하기 {#single-pack-check}&quot;">​</a></h2><p>한쪽 팩에 문제가 있는지는 <strong>한 팩씩 장착해 전원이 들어오는지</strong> 확인하면 알 수 있습니다.</p><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>배터리를 <strong>한쪽만 장착한 상태에서는 로봇을 세우거나 보행시키지 마세요.</strong> 이 점검에서 확인하는 것은 <strong>전원이 들어오는지</strong> 뿐입니다. 전원 확인이 끝나면 즉시 전원을 끄고 다음 단계로 넘어가세요.</p></div></div><ol><li>로봇을 <strong>앉은 자세</strong>로 두고 전원을 끕니다.</li><li>배터리를 <strong>한쪽만</strong> 장착합니다.</li><li>전원을 켜고 <strong>전원이 들어오는지만</strong> 확인합니다.</li><li>전원을 끄고 배터리를 분리합니다.</li><li><strong>반대쪽 배터리만</strong> 장착하고 3번과 같은 방법으로 전원이 들어오는지 확인합니다.</li></ol><p>배터리 분리 · 장착 방법은 <a href="/RBQ/ko/manual/maintenance/battery.html">배터리 교체</a>를 참고하세요.</p><h3 id="result" tabindex="-1">결과 판단 <a class="header-anchor" href="#result" aria-label="Permalink to &quot;결과 판단 {#result}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>결과</th><th>판단</th></tr></thead><tbody><tr><td>양쪽 모두 전원이 들어옴</td><td>두 팩 모두 정상적으로 전원을 공급하고 있습니다</td></tr><tr><td>한쪽만 전원이 들어옴</td><td>전원이 들어오지 않는 팩 또는 해당 커넥터에 문제가 있습니다</td></tr><tr><td>양쪽 모두 전원이 들어오지 않음</td><td>배터리가 아닌 다른 원인입니다</td></tr></tbody></table><h2 id="voltage-imbalance" tabindex="-1">좌우 전압 차이가 클 때 <a class="header-anchor" href="#voltage-imbalance" aria-label="Permalink to &quot;좌우 전압 차이가 클 때 {#voltage-imbalance}&quot;">​</a></h2><p>두 팩의 전압 차이가 크게 벌어지면 문제가 발생할 수 있습니다. 위 점검에서 한쪽만 전원이 들어오거나, 팩을 교체해도 증상이 반복된다면 로봇을 계속 운용하지 말고 <a href="/RBQ/ko/manual/support/">문의</a>해 주세요.</p><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>점검 결과(양쪽 각각 전원이 들어왔는지)를 알려주시면 확인이 빠릅니다. <a href="/RBQ/ko/manual/support/">기술지원 요청</a></p><p>배터리 취급 시 주의사항은 <a href="/RBQ/ko/manual/safety/battery-handling.html">배터리 취급 주의사항</a>을 확인하세요.</p>',13)])])}const b=a(l,[["render",n]]);export{p as __pageData,b as default};
